INSERT INTO `libros`.`libro` (`titulo`, `descripcion`, `idautor`) VALUES ('El código Da Vinci', 'Dan Brown mezcla arte, religión y conspiración en El código Da Vinci, un thriller que arranca con un asesinato en el Louvre y una pista escondida en la Mona Lisa. La trama cuestiona verdades que la Iglesia habría mantenido en secreto.', '1');
INSERT INTO `libros`.`libro` (`titulo`, `descripcion`, `idautor`) VALUES ('El señor de los anillos', 'Un hobbit recibe la misión más peligrosa del mundo conocido: destruir un anillo de poder en las grietas del destino. Para lograrlo, tendrá que atravesar tierras hostiles junto a una comunidad de hombres, elfos y enanos.', '2');
INSERT INTO `libros`.`libro` (`titulo`, `descripcion`, `idautor`) VALUES ('El Principito', 'Antoine de Saint-Exupéry escribió El Principito un año antes de morir, y metió en ese pequeño libro todo lo que pensaba sobre la amistad, la imaginación y lo que los adultos olvidan al crecer. Un piloto varado en el desierto y un niño de otro planeta: una conversación que no se olvida.', '3');
INSERT INTO `libros`.`libro` (`titulo`, `descripcion`, `idautor`) VALUES ('Don Quijote de la Mancha', 'Don Quijote de la Mancha de Miguel de Cervantes es el segundo libro más leído en la historia, solo después de la Biblia. Sancho Panza, los molinos de viento, Dulcinea: personajes y escenas que ya forman parte del idioma español.', '4');
INSERT INTO `libros`.`libro` (`titulo`, `descripcion`, `idautor`) VALUES ('El Alquimista', 'Santiago, un joven pastor andaluz, emprende un viaje por el desierto buscando un tesoro en El Alquimista de Paulo Coelho. Lo que encuentra no es oro: es una comprensión más profunda de sí mismo y del mundo.', '5');
